window.RP_SESSION={"id":"S-ddcb9be818be","messages":[{"id":"RP-0194105","time":"2026-07-16T21:21:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":" 새로운 취미가 생겼습니다.","characters":[]},{"id":"RP-0194106","time":"2026-07-16T21:23:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"뜨개질☆","characters":[]},{"id":"RP-0194107","time":"2026-07-16T21:24:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"뭔가 요새 할일이 없어서 계속 뜨다보니","characters":[]},{"id":"RP-0194108","time":"2026-07-16T21:24:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"데구륵. 쑤윽.","characters":[]},{"id":"RP-0194109","time":"2026-07-16T21:25:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"뜬 부분의 길이가 늘어나 모닥불로 들어갔습니다.","characters":[]},{"id":"RP-0194110","time":"2026-07-16T21:25:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"한번, 뜨개실과 바늘을 쥔 손을 놓아봅니다.","characters":[]},{"id":"RP-0194111","time":"2026-07-16T21:25:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"!모닥불","characters":[]},{"id":"RP-0194112","time":"2026-07-16T21:25:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]},{"id":"RP-0194113","time":"2026-07-16T21:25:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"'잘~타는 구만~'","characters":[]},{"id":"RP-0194114","time":"2026-07-16T21:25:00+09:00","room":"RP","name":"마카리오스 오 르벤","profile":"마카리오스 오 르벤","identity":"reviewed","type":"dialogue","body":"무언가 주섬주섬 가져와서 모닥불 앞에 앉는다.\n\n\"안녕, 모닥불 밥 줘?\"","characters":["P-682d542e2840"]},{"id":"RP-0194115","time":"2026-07-16T21:27:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":" \"그렇게 되버렸군.\"\n\n  지난 20년도 홀라당 태워먹어서 그런건지, 자신의 몇 시간이 걸린 생성물이 눈 앞에서 활활 타오로는 모습에도 하하 웃기나 한다.","characters":[]},{"id":"RP-0194116","time":"2026-07-16T21:31:00+09:00","room":"RP","name":"마카리오스 오 르벤","profile":"마카리오스 오 르벤","identity":"reviewed","type":"dialogue","body":"\"그럼 나도 사이좋게 모닥불에 밥 한번 줘보지.\"\n\n두툼한 고기를 손에 든 채로 모닥불을 바라본다.\n\n\"이상하겠지만 그대로 불덩이에 집어넣어서 고기를 굽는 방식이 있더라고. ...그런데 묘하게 뭘 까먹은 거 같지?\"","characters":["P-682d542e2840"]},{"id":"RP-0194117","time":"2026-07-16T21:31:00+09:00","room":"RP","name":"마카리오스 오 르벤","profile":"마카리오스 오 르벤","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-682d542e2840"]},{"id":"RP-0194118","time":"2026-07-16T21:31:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'마카리오스 오 르벤'의 지능 판정 :\n[10] + [2] = [12]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0194119","time":"2026-07-16T21:31:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":" \"그거 아마 판이나... 꼬치 같은거 필요하지 않나?\"","characters":[]},{"id":"RP-0194120","time":"2026-07-16T21:32:00+09:00","room":"RP","name":"마카리오스 오 르벤","profile":"마카리오스 오 르벤","identity":"reviewed","type":"dialogue","body":"\"참, 활활 타는 불이 아니라 불 붙은 숯에 올려놓는 거였지.\"","characters":["P-682d542e2840"]},{"id":"RP-0194121","time":"2026-07-16T21:32:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"뭘 말하는 건지는 잘 모르겠지만 말야.","characters":[]},{"id":"RP-0194122","time":"2026-07-16T21:32:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"아하.","characters":[]},{"id":"RP-0194123","time":"2026-07-16T21:33:00+09:00","room":"RP","name":"마카리오스 오 르벤","profile":"마카리오스 오 르벤","identity":"reviewed","type":"dialogue","body":"자기 방으로 달려가서 무쇠팬과 삽을 들고와 모닥불에서 숯이 전직한 나무를 꺼내 충분히 팬에 깔아주고 고기를 숯 위로 던져줬다.\n\n\"음, 좋은 냄새.\"","characters":["P-682d542e2840"]},{"id":"RP-0194124","time":"2026-07-16T21:45:00+09:00","room":"RP","name":"올리브","profile":"올리브","identity":"unresolved","type":"dialogue","body":"확실히 좋은 냄새긴 하다. 확실히 어색하기도 하고\n\n \"그러고보니 우리가 여기서 보는 건 처음이로군.\"","characters":[]},{"id":"RP-0194125","time":"2026-07-16T22:00:00+09:00","room":"RP","name":"마카리오스 오 르벤","profile":"마카리오스 오 르벤","identity":"reviewed","type":"dialogue","body":"\"뭐, 나는 길드에 있기보단 혼자서 모험을 떠나거나 방에서 잘 안 나오는 편이라서 얼굴 보기가 힘들거야. 그래도 요즘은 길드에 얼굴 보일려고 노력은 하는데... 쉽진 않네.\"\n\n노릇노릇하게 구워지는 고기를 보며 뒤집을 준비를 한다.","characters":["P-682d542e2840"]},{"id":"RP-0194127","time":"2026-07-17T01:53:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
